from typing import List

def permute(n: int, k: int) -> List[int]:
    memo = {}

    def count_ways(o, e, last_p):
        if o == 0 and e == 0:
            return 1
        state = (o, e, last_p)
        if state in memo:
            return memo[state]

        res = 0
        if last_p == -1:
            if o > 0:
                res += o * count_ways(o - 1, e, 1)
            if e > 0:
                res += e * count_ways(o, e - 1, 0)
        elif last_p == 0:  # Last was even, next must be odd
            if o > 0:
                res = o * count_ways(o - 1, e, 1)
        else:  # Last was odd, next must be even
            if e > 0:
                res = e * count_ways(o, e - 1, 0)

        memo[state] = res
        return res

    total_odds = (n + 1) // 2
    total_evens = n // 2

    # Initial check for k range
    if k > count_ways(total_odds, total_evens, -1):
        return []

    res = []
    used = [False] * (n + 1)
    o_rem = total_odds
    e_rem = total_evens
    last_p = -1
    curr_k = k

    for i in range(n):
        found = False
        for val in range(1, n + 1):
            if not used[val]:
                p = 1 if val % 2 != 0 else 0
                if last_p == -1 or p != last_p:
                    o_next = o_rem - (1 if p == 1 else 0)
                    e_next = e_rem - (1 if p == 0 else 0)

                    # Count how many numbers of parity p are currently unused
                    count_avail_p = 0
                    for v in range(1, n + 1):
                        if not used[v] and (v % 2 != 0) == p:
                            count_avail_p += 1

                    # ways to complete is count_ways / number of choices for this specific slot
                    # Since we fixed 'val', the factor count_avail_p is already accounted for in count_ways.
                    # We divide by it because we are choosing one specific value out of count_avail_p possibilities.
                    ways = count_ways(o_next, e_next, p) // count_avail_p

                    if curr_k <= ways:
                        res.append(val)
                        used[val] = True
                        o_rem = o_next
                        e_rem = e_next
                        last_p = p
                        found = True
                        break
                    else:
                        curr_k -= ways
        if not found:
            return []

    return res

