                            val_p = (val_p * 10 + int(s[i])) % d
                        # This val_p is for substring s[k-P+1...k].
                        # All substrings starting at i < k-P+1 have the same remainder mod d.
                        if val_p == 0:
                            ans += (k - P + 1)
        elif d == 6:
            # Value % 6 == 0 iff Value % 2 == 0 and Value % 3 == 0.
