import heapq

def minOperations(n: int, m: int):
    if is_prime(m): return -1

    # Dijkstra's algorithm for shortest path (minimum cost)
    # State: current value of n
    # Cost: sum of all values taken throughout the process
    pq = [(0, n)]  # (total_cost, current_n)
    dist = {n: 0}

    while pq:
        d, curr = heapq.heappop(pq)

        if curr == m:
            return d

        if d > dist.get(curr, float('inf')):
            continue

        # Generate neighbors by changing digits one by one
        s_curr = str(curr).zfill(len(str(n)))
        for i in range(len(s_curr)):
            digit = int(s_curr[i])

            # Operation 1: Increase digit (not 9)
            if digit < 9:
                next_val = int(s_curr[:i] + str(digit + 1) + s_curr[i+1:])
                if next_val <= 9999 and not is_prime(next_val):
                    new_cost = d + curr + next_val
                    if new_cost < dist.get(next_val, float('inf')):
                        dist[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))

            # Operation 2: Decrease digit (not 0)
            if digit > 0:
                next_val = int(s_curr[:i] + str(digit - 1) + s_curr[i+1:])
                if next_val >= 0 and not is_prime(next_val):
                    new_cost = d + curr + next_val
                    if new_cost < dist.get(next_val, float('inf')):
                        dist[next_val] = new_cost
                        heapq.heappush(pq, (new_cost, next_val))
    return -1

def is_prime(k):
    if k < 2: return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0: return False
    return True
