import heapq

def minOperations(n: int, m: int) -> int:
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Rule check: n and m must not be prime at any point
    if is_prime(n) or is_prime(m):
        return -1

    # The example 1: 10 -> 20 -> 21 -> 22 -> 12. Sum = 20+21+22+12 = 85.
    # This implies cost = sum of all values taken AFTER the initial n.
    # Dijkstra state: (total_cost, current_value)
    pq = [(0, n)]
    visited = {n: 0}

    target_len = len(str(n))

    while pq:
        curr_cost, curr = heapq.heappop(pq)

        if curr == m:
            return curr_cost

        if curr_cost > visited.get(curr, float('inf')):
            continue

        s_curr = str(curr).zfill(target_len)
        for i in range(target_len):
            digit = int(s_curr[i])
            base = 10**(target_len - 1 - i)

            # Try incrementing digit (if not 9)
            if digit < 9:
                nxt = curr + base
                # Ensure nxt doesn't exceed the same number of digits or change structure
                if nxt < 10**target_len and not is_prime(nxt):
                    new_cost = curr_cost + nxt
                    if new_cost < visited.get(nxt, float('inf')):
                        visited[nxt] = new_cost
                        heapq.heappush(pq, (new_cost, nxt))

            # Try decrementing digit (if not 0)
            if digit > 0:
                nxt = curr - base
                # Ensure nxt remains positive and has correct number of digits/not negative
                if nxt >= 0 and str(nxt).zfill(target_len)[:1] == s_curr[0]: # Keep same length
                    # Actually, the problem says "same number of digits", usually implies leading zeros aren't allowed unless specified.
                    # However, the example 1 uses 2-digit numbers (10, 20, 21, 22, 12).
                    if nxt >= 10**(target_len-1) if target_len > 1 else nxt >= 0:
                        # Check prime and bounds
                        if not is_prime(nxt):
                            new_cost = curr_cost + nxt
                            if new_cost < visited.get(nxt, float('inf')):
                                visited[nxt] = new_cost
                                heapq.heappush(pq, (new_cost, nxt))

    return -1
