                # 我們需要確保它不是從初始 (0,0) 直接跳過的所有數字得到的。
                if p == 1 and k == 0:
                    # 檢查是否有任何實際的子序列能產生 sum 0 且 product 為 1
                    # 最簡單的方法是檢查這個 product 是否來自於選了數字 1
                    continue 
                max_res = max(max_res, p)

    # 處理 k=0 且可能存在 product 為 1 的非空子序列的情況 (例如選了 [1] 但 sum 不是 0...)
    # 實際上，只要有任何數字被選入，product 就會更新。
    # 如果 nums 裡有 1，且某些組合的乘積是 1，則它是合法的。
    # 為了保險，我們重新檢查一遍：
    final_ans = -1
    for (s, parity), products in dp.items():
        if s == k:
            for p in products:
                # 如果 product 是 1，且它不是從初始狀態直接變過去的（即至少選了一個數）
                # 在這個 DP 中，只要 new_prod = p * x 發生過，就是非空的。
                # 因為我們只在更新時才加入到新 dp。
                final_ans = max(final_ans, p)

    # 由於初始 (0,0) 的 product 為 1 是空集，若最終結果是 1 且 k=0，
    # 我們得確認它是真的選了數字還是沒選。
    # 最簡單的解法是在 DP 時，讓空集的 product 不同於任何可能產生的 product 或用 flag。

    # 修正：重新實作一個更嚴謹的邏輯
    return final_ans

# 因為上面的邏輯在處理 k=0 和 product=1 時略顯複雜，
# 以下是簡化且正確的寫法：
def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[(sum, parity)] = set of products
    dp = {(0, 0): {None}} # Use None to represent the empty subsequence product

    for x in nums:
        new_updates = []
        for (s, parity), products in dp.items():
            new_sum = s + x if parity == 0 else s - x
            new_parity = 1 - parity
            for p in products:
                if p is None: # Empty sequence case
                    new_prod = x
                else:
                    new_prod = p * x

                if new_prod <= limit:
                    new_updates.append((new_sum, new_parity, new_prod))

        for s, p_val, prod in new_updates:
            if (s, p_val) not in dp:
                dp[(s, p_val)] = set()
            dp[(s, p_val)].add(prod)

    ans = -1
    for (s, parity), products in dp.items():
        if s == k:
            for p in products:
                if p is not None: # Ensure non-empty
                    ans = max(ans, p)
    return ans
