from typing import List

def maxProduct(nums: List[int], k: int, limit: int) -> int:
    # dp[alt_sum][product] = boolean (is reachable)
    # Since nums[i] are small and limit is small, we can use a dictionary of sets or 2D array.
    # However, alt_sum can be negative. Let's use a dict for the current state: sum -> {products}
    # Because we need to know if it's even or odd index in the subsequence,
    # we track (current_alt_sum, current_product, is_next_even)

    # dp[alt_sum][product] = max_product reached? No, just reachability.
    # To optimize: dp[alt_sum] = set of products
    # Because we need to know the parity of the index in the subsequence:
    # even_idx_dp[sum] = set of products ending at an even position (so next is odd)
    # odd_idx_dp[sum] = set of products ending at an odd position (so next is even)

    # Initial state: nothing chosen. 
    # To handle the first element (index 0, which is even), we can imagine a virtual "odd" step.
    # Or just initialize with empty sum and special flag.

    # dp[sum][parity] = set of products
    # parity 0: next element will be at an even index (e.g., first element)
    # parity 1: next element will be at an odd index
    dp = {} # (alt_sum, parity) -> set of products

    # To handle the "non-empty" requirement and alternating sum correctly:
    # A subsequence [x] has sum x (even index 0).
    # A subsequence [x, y] has sum x - y (index 0 even, index 1 odd).
    # A subsequence [x, y, z] has sum x - y + z.

    for x in nums:
        new_dp = {}
        # Option 1: Start a new subsequence with x (it's at index 0, which is even)
        # This contributes to the "next is odd" state for future elements
        state1 = (x, 1)
        if state1 not in new_dp: new_dp[state1] = set()
        new_dp[state1].add(x)

        for (s, p), prods in dp.items():
            # Option 2: Add x to existing subsequence
            # If current parity is 0 (next index is even), new sum is s + x
            if p == 0:
                new_s = s + x
                new_p = 1
                state = (new_s, new_p)
                if state not in new_dp: new_dp[state] = set()
                for pr in prods:
                    if pr * x <= limit:
                        new_dp[state].add(pr * x)
            # If current parity is 1 (next index is odd), new sum is s - x
            else:
                new_s = s - x
                new_p = 0
                state = (new_s, new_p)
                if state not in new_dp: new_dp[state] = set()
                for pr in prods:
                    if pr * x <= limit:
                        new_dp[state].add(pr * x)

        # Merge new_dp into dp
        for key, val in new_dp.items():
            if key not in dp: dp[key] = set()
            dp[key].update(val)

    ans = -1
    for (s, p), prods in dp.items():
        if s == k:
            for pr in prods:
                if pr <= limit:
                    ans = max(ans, pr)
    return ans
