from typing import List
from functools import lru_cache

def maxScore(grid: List[List[int]]) -> int:
    rows = len(grid)
    cols = len(grid[0])

    @lru_cache(None)
    def solve(row, used_values):
        if row == rows:
            return 0

        # Option 1: Skip current row
        res = solve(row + 1, used_values)

        # Option 2: Pick a cell from current row
        for col in range(cols):
            val = grid[row][col]
            if not (used_values & (1 << val)):
                res = max(res, val + solve(row + 1, used_values | (1 << val)))

        return res

    # Values are up to 100, so use bitmask for values 1-100
    return solve(0, 0)
