from typing import List

def sortMatrix(grid: List[List[int]]) -> List[List[int]]:
    n = len(grid)
    # Bottom-left triangle (including middle diagonal): r - c >= 0
    # Top-right triangle: r - c < 0

    # Process bottom-left diagonals (r - c >= 0)
    for k in range(-(n - 1), n + 1):
        diag = []
        # For a diagonal, r - c = k. Let's find all points.
        # Since we only care about r - c >= 0:
        for r in range(n):
            c = r - k
            if 0 <= c < n and r - c >= 0:
                diag.append(grid[r][c])

        if diag:
            # Sort non-increasing (descending)
            diag.sort(reverse=True)
            idx = 0
            for r in range(n):
                c = r - k
                if 0 <= c < n and r - c >= 0:
                    grid[r][c] = diag[idx]
                    idx += 1

    # Process top-right diagonals (r - c < 0)
    for k in range(-(n - 1), n + 1):
        diag = []
        for r in range(n):
            c = r - k
            if 0 <= c < n and r - c < 0:
                diag.append(grid[r][c])

        if diag:
            # Sort non-decreasing (ascending)
            diag.sort()
            idx = 0
            for r in range(n):
                c = r - k
                if 0 <= c < n and r - c < 0:
                    grid[r][c] = diag[idx]
                    idx += 1

    return grid
